BASIC.calculation:
// Labor Code art.103: a monthly salary paid twice a month pays half each run. A day rate pays the working days of the period,
// less the holidays that HOLIDAY_WORK, SPECIAL_HOLIDAY_WORK and DAILY_HOLIDAY_PAY price at their own full multiple; an unworked
// special day is no work, no pay. ctx.base_pay has already taken off unpaid days, joiners and leavers.
const terms = ctx.subject.employment.terms;
const employer = ctx.subject.employer;
const coverage = ctx.run.salary_coverage;
const unit = get(terms, 'rate.unit', 'MONTHLY');
if (unit === 'MONTHLY') return get(employer, 'payment_schedule.frequency', '') === 'SEMI_MONTHLY' ? ctx.base_pay / 2 : ctx.base_pay;
if (unit !== 'DAILY' || ["MANAGERIAL", "DOMESTIC", "FIELD_PERSONNEL", "TASK_BASIS", "PIECE_RATE"].includes(get(terms, 'statutory_work_category', ''))) return ctx.base_pay;
const facts = get(employer, 'entity_extension_data', {});
const off = get(employer, 'payment_schedule.non_working_weekdays', [0, 6]);
const small = get(facts, 'retail_or_service_establishment', false) === true && get(facts, 'small_establishment', false) === true;
const priced = ctx.work.days.filter((d) => {
	const kind = get(d, 'holiday_kind', '');
	// Every holiday kind except MAKEUP_WORKDAY earns the premium; a makeup workday is a plain working day.
	if (kind === '' || kind === 'MAKEUP_WORKDAY' || get(d, 'day_type', '') !== 'WORK') return false;
	if (d.date < coverage.from || d.date > coverage.to || off.includes(weekday(d.date))) return false;
	const special = kind === 'SPECIAL_HOLIDAY' || kind === 'DOUBLE_SPECIAL';
	return special || !small;
}).length;
return Math.max(0, ctx.base_pay - ctx.day_rate * priced);

OVERTIME.conversion:
// Labor Code art.87; DOLE Handbook on Workers' Statutory Monetary Benefits 2024 ch.4 §C: hours beyond the contract's normal hours of work carry the day's overtime multiple.
const terms = get(ctx.subject.employment, 'terms', {});
const hours = Number(get(terms, 'normal_hours_per_day', 0));
// The hour is the day over its hours, unrounded; an employer's own quoted hour stands.
const hour = hours > 0 && get(ctx.subject.employer, 'pay_methods.overtime_hour_basis', 'STATUTORY') === 'STATUTORY' ? ctx.day_rate / hours : ctx.hour_rate;
// Labor Code arts.87, 93(a): an employer's own rest-day hourly multiple stands where it pays more.
const multiple = Number(get(ctx.subject.employer, 'pay_methods.rest_day_hourly_multiplier', 0));
const premium = (d) => {
	const rest = get(d, 'day_type', '') === 'REST';
	const kind = get(d, 'holiday_kind', '');
	if (kind === 'DOUBLE_HOLIDAY') return rest ? ctx.lookup.overtime_multiples.double_holiday_rest : ctx.lookup.overtime_multiples.double_holiday;
	if (kind === 'DOUBLE_SPECIAL') return rest ? ctx.lookup.overtime_multiples.double_special_rest : ctx.lookup.overtime_multiples.double_special;
	if (kind === 'SPECIAL_HOLIDAY') return rest ? ctx.lookup.overtime_multiples.special_rest : ctx.lookup.overtime_multiples.special;
	// Every holiday kind except MAKEUP_WORKDAY earns the premium; a makeup workday is a plain working day.
	if (kind !== '' && kind !== 'MAKEUP_WORKDAY') return rest ? ctx.lookup.overtime_multiples.holiday_rest : ctx.lookup.overtime_multiples.holiday;
	return rest ? Math.max(ctx.lookup.overtime_multiples.rest, multiple) : ctx.lookup.overtime_multiples.ordinary;
};
const quantity = sum(
	ctx.work.days.map((d) =>
		Math.min(
			Number(get(d, 'overtime_hours', 0)),
			Math.max(0, Number(get(d, 'worked_hours', 0)) - hours)
		) * premium(d)
	)
);
return quantity * hour;

REST_DAY_WORK.conversion:
const terms = get(ctx.subject.employment, 'terms', {});
const hours = Number(get(terms, 'normal_hours_per_day', 0));
// The hour is the day over its hours, unrounded; an employer's own quoted hour stands.
const hour = hours > 0 && get(ctx.subject.employer, 'pay_methods.overtime_hour_basis', 'STATUTORY') === 'STATUTORY' ? ctx.day_rate / hours : ctx.hour_rate;
// Labor Code art.93(a)-(b); DOLE Handbook 2024 ch.3 §D: the day rate divides the contract week's working days, so the rest day is unpaid and its work adds the full multiple.
// Every holiday kind except MAKEUP_WORKDAY earns the premium; a makeup workday is a plain working day.
const holiday = (d) => {
	const kind = get(d, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
const quantity = sum(
	ctx.work.days
		.filter((d) => get(d, 'day_type', '') === 'REST' && !holiday(d))
		.filter((d) => get(d, 'worked', false) === true)
		.map((d) => Math.min(Number(get(d, 'worked_hours', 0)), hours))
);
// Labor Code art.93(a): an employer's own rest-day hourly multiple stands where it pays more.
const multiple = Number(get(ctx.subject.employer, 'pay_methods.rest_day_hourly_multiplier', 0));
return quantity * Math.max(ctx.lookup.day_multiples.rest, multiple) * hour;

OFF_DAY_WORK.conversion:
const terms = get(ctx.subject.employment, 'terms', {});
const unit = get(get(terms, 'rate', {}), 'unit', 'MONTHLY');
const week = Number(get(terms, 'normal_days_per_week', 7));
// DOLE Handbook 2024 ch.2 §E: an off day outside the contract week is unpaid, and work on it is paid 100%; a seven-day week's wage already pays every day.
if (unit === 'DAILY' || week >= 7) return 0;
const hours = Number(get(terms, 'normal_hours_per_day', 0));
// The hour is the day over its hours, unrounded; an employer's own quoted hour stands.
const hour = hours > 0 && get(ctx.subject.employer, 'pay_methods.overtime_hour_basis', 'STATUTORY') === 'STATUTORY' ? ctx.day_rate / hours : ctx.hour_rate;
// Every holiday kind except MAKEUP_WORKDAY earns the premium; a makeup workday is a plain working day.
const holiday = (d) => {
	const kind = get(d, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
const quantity = sum(
	ctx.work.days
		.filter((d) => get(d, 'day_type', '') === 'OFF' && !holiday(d))
		.filter((d) => get(d, 'worked', false) === true)
		.map((d) => Math.min(Number(get(d, 'worked_hours', 0)), hours))
);
return quantity * hour;

HOLIDAY_WORK.eligibility:
if (ctx.lookup.premium_excluded_categories.includes(get(ctx.subject.employment, 'terms.statutory_work_category', ''))) return false;
if (get(ctx.subject.employer, 'entity_extension_data.retail_or_service_establishment', false) !== true) return true;
return get(ctx.subject.employer, 'entity_extension_data.small_establishment', false) !== true;

HOLIDAY_WORK.conversion:
const terms = get(ctx.subject.employment, 'terms', {});
const unit = get(get(terms, 'rate', {}), 'unit', 'MONTHLY');
const hours = Number(get(terms, 'normal_hours_per_day', 0));
// The hour is the day over its hours, unrounded; an employer's own quoted hour stands.
const hour = hours > 0 && get(ctx.subject.employer, 'pay_methods.overtime_hour_basis', 'STATUTORY') === 'STATUTORY' ? ctx.day_rate / hours : ctx.hour_rate;
// Every holiday kind except MAKEUP_WORKDAY earns the premium; a makeup workday is a plain working day.
const holiday = (d) => {
	const kind = get(d, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
// This row prices the regular holiday class; special days have their own row.
const regular = (d) => {
	const kind = get(d, 'holiday_kind', '');
	return holiday(d) && kind !== 'SPECIAL_HOLIDAY' && kind !== 'DOUBLE_SPECIAL';
};
const multiple = (d) => {
	const rest = get(d, 'day_type', '') === 'REST';
	if (get(d, 'holiday_kind', '') === 'DOUBLE_HOLIDAY') return rest ? ctx.lookup.day_multiples.double_holiday_rest : ctx.lookup.day_multiples.double_holiday;
	return rest ? ctx.lookup.day_multiples.holiday_rest : ctx.lookup.day_multiples.holiday;
};
const premium = (d) => multiple(d) - (unit === 'DAILY' ? 0 : 1);
const quantity = sum(
	ctx.work.days
		.filter((d) => regular(d))
		.filter((d) => get(d, 'worked', false) === true)
		.map((d) => Math.min(Number(get(d, 'worked_hours', 0)), hours) * premium(d))
);
return quantity * hour;

SPECIAL_HOLIDAY_WORK.conversion:
const terms = get(ctx.subject.employment, 'terms', {});
const unit = get(get(terms, 'rate', {}), 'unit', 'MONTHLY');
const hours = Number(get(terms, 'normal_hours_per_day', 0));
// The hour is the day over its hours, unrounded; an employer's own quoted hour stands.
const hour = hours > 0 && get(ctx.subject.employer, 'pay_methods.overtime_hour_basis', 'STATUTORY') === 'STATUTORY' ? ctx.day_rate / hours : ctx.hour_rate;
// Every holiday kind except MAKEUP_WORKDAY earns the premium; a makeup workday is a plain working day.
const holiday = (d) => {
	const kind = get(d, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
// This row prices the special-day class; regular holidays have their own row.
const special = (d) => {
	const kind = get(d, 'holiday_kind', '');
	return holiday(d) && (kind === 'SPECIAL_HOLIDAY' || kind === 'DOUBLE_SPECIAL');
};
const premium = (d) => {
	const rest = get(d, 'day_type', '') === 'REST';
	const double = get(d, 'holiday_kind', '') === 'DOUBLE_SPECIAL';
	const restMultiple = double ? ctx.lookup.day_multiples.double_special_rest : ctx.lookup.day_multiples.special_rest;
	const workMultiple = double ? ctx.lookup.day_multiples.double_special : ctx.lookup.day_multiples.special;
	const multiple = rest ? restMultiple : workMultiple;
	// Labor Code art.93(c); DOLE Handbook 2024 ch.3 §D: a working-day special day is paid inside the month's day rate, so only the excess is added; a rest day is not.
	return unit === 'DAILY' || rest ? multiple : multiple - 1;
};
const quantity = sum(
	ctx.work.days
		.filter((d) => special(d))
		.filter((d) => get(d, 'worked', false) === true)
		.map((d) => Math.min(Number(get(d, 'worked_hours', 0)), hours) * premium(d))
);
return quantity * hour;

