const terms = get(ctx.subject.employment, 'terms', {});
const hours = Number(get(terms, 'normal_hours_per_day', 0));
// The hour is the day over its hours, unrounded; an employer's own quoted hour stands.
const hour = hours > 0 && get(ctx.subject.employer, 'pay_methods.overtime_hour_basis', 'STATUTORY') === 'STATUTORY' ? ctx.day_rate / hours : ctx.hour_rate;
const zone = get(ctx.subject.employer, 'time_zone', 'Asia/Manila');
const overtime = (d) => Math.min(
	Number(get(d, 'overtime_hours', 0)),
	Math.max(0, Number(get(d, 'worked_hours', 0)) - hours)
);
const nightMinutes = (d, field) =>
	clock_window_minutes(get(d, field, []), zone, ctx.lookup.night_from, ctx.lookup.night_to, ctx.as_of) / 60;
const overtimeNight = (d) => Math.min(nightMinutes(d, 'overtime_intervals'), overtime(d));
const dayMultiple = (d) => {
	const rest = get(d, 'day_type', '') === 'REST';
	const kind = get(d, 'holiday_kind', '');
	if (kind === 'DOUBLE_HOLIDAY') return rest ? ctx.lookup.day_multiples.double_holiday_rest : ctx.lookup.day_multiples.double_holiday;
	if (kind === 'DOUBLE_SPECIAL') return rest ? ctx.lookup.day_multiples.double_special_rest : ctx.lookup.day_multiples.double_special;
	if (kind === 'SPECIAL_HOLIDAY') return rest ? ctx.lookup.day_multiples.special_rest : ctx.lookup.day_multiples.special;
	// Every holiday kind except MAKEUP_WORKDAY earns the premium; a makeup workday is a plain working day.
	if (kind !== '' && kind !== 'MAKEUP_WORKDAY') return rest ? ctx.lookup.day_multiples.holiday_rest : ctx.lookup.day_multiples.holiday;
	return rest ? ctx.lookup.day_multiples.rest : ctx.lookup.day_multiples.ordinary;
};
const overtimeMultiple = (d) => {
	const rest = get(d, 'day_type', '') === 'REST';
	const kind = get(d, 'holiday_kind', '');
	if (kind === 'DOUBLE_HOLIDAY') return rest ? ctx.lookup.overtime_multiples.double_holiday_rest : ctx.lookup.overtime_multiples.double_holiday;
	if (kind === 'DOUBLE_SPECIAL') return rest ? ctx.lookup.overtime_multiples.double_special_rest : ctx.lookup.overtime_multiples.double_special;
	if (kind === 'SPECIAL_HOLIDAY') return rest ? ctx.lookup.overtime_multiples.special_rest : ctx.lookup.overtime_multiples.special;
	// Every holiday kind except MAKEUP_WORKDAY earns the premium; a makeup workday is a plain working day.
	if (kind !== '' && kind !== 'MAKEUP_WORKDAY') return rest ? ctx.lookup.overtime_multiples.holiday_rest : ctx.lookup.overtime_multiples.holiday;
	return rest ? ctx.lookup.overtime_multiples.rest : ctx.lookup.overtime_multiples.ordinary;
};
// Labor Code art.86: an employer that pays the premium on the whole clocked span, unpaid break and overtime included, at the ordinary hour keeps its method on any shift where it pays more.
const basis = get(ctx.subject.employer, 'pay_methods.night_differential_basis', 'WORKED');
const span = basis === 'CLOCK_SPAN';
const clocked = (d) => {
	const worked = get(d, 'intervals', []);
	if (worked.length === 0) return 0;
	const start = worked.reduce((a, i) => (i.start < a ? i.start : a), worked[0].start);
	const end = worked.reduce((a, i) => (i.end > a ? i.end : a), worked[0].end);
	return clock_window_minutes([{ start, end }], zone, ctx.lookup.night_from, ctx.lookup.night_to, ctx.as_of) / 60;
};
const quantity = sum(
	ctx.work.days.map((d) => {
		const night = Math.max(0, nightMinutes(d, 'intervals') - overtimeNight(d));
		const statute = (night * dayMultiple(d) + overtimeNight(d) * overtimeMultiple(d)) * ctx.lookup.multiplier;
