		if (basis === 'WHOLE_NIGHT' && night > 0) return Math.max(statute, 8 * dayMultiple(d) * ctx.lookup.multiplier);
		return span ? Math.max(statute, clocked(d) * ctx.lookup.multiplier) : statute;
	})
);
