DOUBLE_HOLIDAY_UNWORKED.conversion:
const rate = get(ctx.subject.employment, 'terms.rate', {});
const unit = get(rate, 'unit', 'MONTHLY');
// Every holiday kind except MAKEUP_WORKDAY earns the premium; a makeup workday is a plain working day.
const holiday = (d) => {
	const kind = get(d, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
// leave_paid marks the nearest preceding work day as paid leave, which is not an unpaid absence.
const workDay = (p) => {
	if (get(p, 'day_type', '') !== 'WORK') return false;
	return !holiday(p) || get(p, 'worked', false) === true;
};
const between = (q, p, d) => get(q, 'date', '') > get(p, 'date', '') && get(q, 'date', '') < get(d, 'date', '');
const unpaidBefore = (d) =>
	ctx.work.days.some((p) => {
		if (!(get(p, 'date', '') < get(d, 'date', ''))) return false;
		if (!workDay(p)) return false;
		if (ctx.work.days.some((q) => between(q, p, d) && workDay(q))) return false;
		if (get(p, 'worked', false) === true) return false;
		return get(p, 'leave_paid', false) !== true;
	});
const owed = (d) => {
	if (get(d, 'holiday_kind', '') !== 'DOUBLE_HOLIDAY') return false;
	if (get(d, 'worked', false) === true) return false;
	return unit !== 'DAILY' || !unpaidBefore(d);
};
const quantity = sum(ctx.work.days.filter((d) => owed(d)).map(() => 1));
return quantity * ctx.day_rate;

