SSS.eligibility:
if (get(ctx.subject.employment, 'engagement', 'EMPLOYEE') === 'PAYEE') return false;
const p = ctx.lookup;
// Twice a month the second run settles the month's contribution whatever it pays itself. An off-cycle run moves it only with ordinary wages.
const now = Number(get(ctx.subtotals, 'ORDINARY_WAGES', ctx.base_pay));
const offCycle = get(ctx.run, 'kind', '') === 'OFF_CYCLE';
const month = get(ctx.balances, 'month', {});
const held = String(ctx.run.pay_date).slice(0, 7) + '.ORDINARY_WAGES';
const coverage = ctx.run.salary_coverage;
const halfMonth = String(coverage.to) < String(month_end(coverage.from)) || String(coverage.from) > String(month_start(coverage.from));
const earlier = (offCycle || halfMonth) && Object.hasOwn(month, held) ? Number(month[held]) : 0;
const base = offCycle && now === 0 ? 0 : Math.max(0, now + earlier);
const facts = get(ctx.subject.employment, 'employee_extension_data', {});
const category = get(ctx.subject.employment.terms, 'statutory_work_category', '');
const domestic = category === 'DOMESTIC';
const exempt = get(facts, 'statutory.SSS.exempt_by_totalisation', false) === true;
const dob = get(ctx.subject.employment, 'payroll.date_of_birth', '');
const age = dob === '' ? 0 : age_on(dob, add_days(ctx.run.salary_coverage.from, -1));
const start = get(ctx.subject.employment, 'service_started_on', get(ctx.subject.employment, 'effective_range.from', ''));
const before60 = get(facts, 'statutory.SSS.covered_before_60', false) === true ||
	(dob !== '' && start !== '' && age_on(dob, start) < p.ordinary_coverage_age_years);
const firstMonth = domestic && start !== '' && calendar_completed_months(start, ctx.run.salary_coverage.from) < 1;
if (base <= 0) return false;
if (exempt) return false;
if (firstMonth) return false;
if (age >= p.extended_coverage_age_years) return false;
return age < p.ordinary_coverage_age_years || before60;

SSS.employee_amount:
const p = ctx.lookup;
// Twice a month the first run charges half of the month its own wages imply; the second charges what the month's actual wages leave, and a person with one run that month is charged whole.
const month = get(ctx.balances, 'month', {});
const heldIn = (paid, code) => (Object.hasOwn(month, paid + '.' + code) ? Number(month[paid + '.' + code]) : 0);
const paidMonth = String(ctx.run.pay_date).slice(0, 7);
const coverage = ctx.run.salary_coverage;
const wholeMonth =
	String(coverage.from) === String(month_start(coverage.from)) && String(coverage.to) === String(month_end(coverage.from));
const separate = get(ctx.run, 'kind', '') !== 'OFF_CYCLE' && wholeMonth && heldIn(paidMonth, 'BASIC') > 0;
const earlier = (code) => (separate ? 0 : heldIn(paidMonth, code));
const before = earlier('ORDINARY_WAGES');
const exit = get(ctx.subject.employment, 'effective_range.to', null);
const firstRun = Number(coverage.to.slice(8, 10)) <= 15;
const alone = firstRun ? exit !== null && exit <= coverage.to : get(ctx.subject.employment, 'effective_range.from', '') >= coverage.from;
const split = get(ctx.subject.employer, 'payment_schedule.frequency', '') === 'SEMI_MONTHLY' && !alone && before === 0;
// Company method (pay_methods.contribution_split FIRST_RUN): the first run charges the whole month on its own wages plus the second half's basic and agreed allowances, less one paid whole with the closing run; the second run settles the month's actual wages.
const whole = split && firstRun && get(ctx.subject.employer, 'pay_methods.contribution_split', 'EVEN') === 'FIRST_RUN';
const runs = split && !whole ? 2 : 1;
const now = Math.max(0, Number(get(ctx.subtotals, 'ORDINARY_WAGES', ctx.base_pay)));
const agreed = get(ctx.subject.employment.terms, 'allowances', {});
const rest = whole
	? (ctx.month_wage + sum(Object.keys(agreed).map((code) => Number(get(agreed, code + '.amount', 0))))) / 2
	: 0;
const base = before > 0 ? before + now : now * runs + rest;
const category = get(ctx.subject.employment.terms, 'statutory_work_category', '');
const domestic = category === 'DOMESTIC';
const low = domestic && base < p.domestic_threshold;
const credit = low
	? Math.max(round(base, p.salary_credit_step, 'HALF_UP'), p.domestic_salary_credit_floor)
	: clamp(round(base, p.salary_credit_step, 'HALF_UP'), p.minimum_salary_credit, p.maximum_salary_credit);
const regular = Math.min(credit, p.regular_fund_salary_credit_ceiling);
return (low ? 0 : round(regular * p.sss_employee_rate / runs, p.minor_unit, 'HALF_UP')) - earlier('SSS.employee');

