const category = get(employment.terms, 'statutory_work_category', '');
if (get(facts, 'statutory.WTAX.treaty_exempt', false) === true) return 0;
const now = (code) => Number(get(ctx.subtotals, code, 0));
const before = (code) => Number(get(ctx.balances, 'ytd.' + code, 0));
const year = (code) => now(code) + before(code);
// RR 11-2018 s.2.79(B)(5)(b) Step 2(c): a manager's fringe is the FBT scheme's; rank-and-file fringe is compensation.
const fringe = ['MANAGERIAL', 'SUPERVISORY'].includes(category) ? 0 : now('FRINGE_BENEFIT') - now('GROSS');
if (get(employment.terms, 'residency_status', 'RESIDENT') === 'NON_RESIDENT_ALIEN_NETB') {
	return round((now('GROSS') + fringe) * p.nonresident_rate, p.minor_unit, 'HALF_UP');
}
const domestic = category === 'DOMESTIC';
const unit = get(employment.terms, 'rate.unit', 'MONTHLY');
const region = get(employment, 'terms.work_region', get(employer, 'region', ''));
const table = domestic ? p.minimum_wage_domestic : p.minimum_wage_by_region;
const rates = table
	.filter((entry) => entry.region === region && entry.from <= coverage.to)
	.toSorted((a, b) => (a.from > b.from ? -1 : 1));
const floor = rates.length === 0 ? 0 : Number(rates[0].monthly);
const daysPerYear = 365 - 52 * (7 - Number(get(employment.terms, 'normal_days_per_week', 6)));
// The table's monthly figure is the wage order's daily rate × 313 ÷ 12: the order fixes the day, whatever the work week.
const dailyFloor = (floor * 12) / 313;
const monthlyRate = unit === 'MONTHLY' ? ctx.month_wage : (ctx.day_rate * daysPerYear) / 12;
