const amount = (row) => (get(row, 'ceiling_days', null) == null ? row.ceiling : get(row, 'ceiling_days', null) * ctx.day_rate);
const yearCeiling = (row) =>
	amount(row) * (Math.floor((lastMonth - 1) / row.months) - Math.floor((firstMonth - 1) / row.months) + 1);
const zone = get(ctx.subject.employer, 'time_zone', 'Asia/Manila');
const night = (d) => clock_window_minutes(get(d, 'intervals', []), zone, p.night_window_start, p.night_window_end, ctx.as_of) > 0;
const mealDays = ctx.work.days.filter((d) => Number(get(d, 'overtime_hours', 0)) > 0 || night(d)).length;
