const held = get(ctx.balances, 'statutory_contribution', {});
const heldOf = (code) => (Object.hasOwn(held, code) ? Number(held[code]) : 0);
// A correction entry of this run that deducts a contribution is a contribution deducted too; one that gives a closed month's back returns the employee's own money and is not pay.
const charged = sum(schemes.map((code) => Number(get(ctx.statutory, code + '.employee', 0)) + Math.max(0, Number(get(ctx.posted, code + '.employee', 0)))));
