	const ceiling = (row) => (row.months === 12 ? Math.max(0, amount(row) - paid(row, before)) : (amount(row) * share) / row.months);
	const excess = mealExcess + sum(p.de_minimis.map((row) => Math.max(0, paid(row, now) - ceiling(row))));
	const taxExcess = get(ctx.subject.employer, 'pay_methods.benefit_exclusion', 'POOLED') === 'EXCESS_TAXED';
	const used = before('ADDITIONAL_WAGES') - before('ORDINARY_WAGES') +
		(taxExcess ? 0 : sum(p.de_minimis.map((row) => Math.max(0, paid(row, before) - yearCeiling(row)))));
	const benefits = now('ADDITIONAL_WAGES') - now('ORDINARY_WAGES') + excess;
	const pool = p.annual_bonus_and_other_benefits;
	// An employer may tax what a benefit pays past its tax-free limit in the month it is paid, leaving the yearly exclusion to the thirteenth month and bonuses; the year's last pay settles it.
	const taxedNow = taxExcess ? excess : 0;
	const period = taxable(now, charged) + fringe + taxedNow + Math.max(0, used + benefits - taxedNow - pool) - Math.max(0, used - pool);
	const bands = days <= 1 ? p.daily_tax : days <= 7 ? p.weekly_tax : days <= 16 ? p.semi_monthly_tax : p.monthly_tax;
	// RR 11-2018 s.2.79(B)(3): supplementary pay is taxed with the period's regular pay on its column. An off-cycle run has
	// none of its own, so it stands on the taxable pay the memo row kept, plus what this month's earlier bonuses were taxed on.
	const paidMonth = paidOn.slice(0, 7);
	const memo = (month) => heldIn(month, 'WTAX_TAXABLE_PAY.employer');
	const lastTaxable = memo(String(add_months(paidMonth + '-01', -1)).slice(0, 7));
	const earlier = heldIn(paidMonth, 'ADDITIONAL_WAGES') - heldIn(paidMonth, 'ORDINARY_WAGES');
	const taxedEarlier =
		Math.max(0, used - pool) -
		Math.max(0, used - earlier - pool);
	// A second salary in the pay month is another payroll period, taxed on its own column.
	const separate = !offCycle && days > 16 && heldIn(paidMonth, 'BASIC') > 0;
	// RR 11-2018 Annex E: a later run of the month takes the month's total through the monthly column, less what the month
	// withheld, so the month's runs withhold what one monthly run does. The month's salary run settles a bonus ahead of it the same way.
	if (!separate && (memo(paidMonth) > 0 || (!offCycle && days > 16 && taxedEarlier > 0))) {
		const monthTaxable = (minimumWageEarner ? 0 : memo(paidMonth)) + taxedEarlier + period;
		return round(ladder(Math.max(0, monthTaxable), days > 7 ? p.monthly_tax : bands), p.minor_unit, 'HALF_UP') - heldIn(paidMonth, 'WTAX.employee');
	}
	const regular = !offCycle ? 0 : (minimumWageEarner ? 0 : (lastTaxable > 0 ? lastTaxable : monthlyRate) * share) + taxedEarlier;
	return round(ladder(Math.max(0, regular + period), bands) - ladder(regular, bands), p.minor_unit, 'HALF_UP');
}
// RR 11-2018 s.2.79(B)(5)(b): the year's taxable pay with a previous employer's, less the year's withholding.
const taxYear = Number(paidOn.slice(0, 4));
const sameYear = Number(get(facts, 'previous_employer_year', taxYear)) === taxYear;
const previous = (key) => (sameYear ? Number(get(facts, key, 0)) : 0);
const yearBenefits = year('ADDITIONAL_WAGES') - year('ORDINARY_WAGES') + mealExcess +
	sum(p.de_minimis.map((row) => Math.max(0, paid(row, year) - yearCeiling(row))));
const yearTaxable = taxable(year, charged + sum(schemes.map((code) => heldOf(code + '.employee')))) + fringe +
	Math.max(0, yearBenefits - p.annual_bonus_and_other_benefits) + previous('previous_employer_taxable_compensation');
const due = round(ladder(Math.max(0, yearTaxable), p.annual_tax), p.minor_unit, 'HALF_UP') -
	heldOf('WTAX.employee') - previous('previous_employer_tax_withheld');
return due;

FBT.eligibility:
const classification = get(ctx.subject.employment.terms, 'statutory_work_category', '');
const base = Math.max(0, ctx.subtotals.FRINGE_BENEFIT - ctx.subtotals.GROSS);
return ['MANAGERIAL', 'SUPERVISORY'].includes(classification) && base > 0;

FBT.employer_amount:
const base = Math.max(0, ctx.subtotals.FRINGE_BENEFIT - ctx.subtotals.GROSS);
if (base <= 0) return 0;
const special = get(ctx.subject.employment.terms, 'residency_status', 'RESIDENT') === 'NON_RESIDENT_ALIEN_NETB';
const share = special ? ctx.lookup.special_nonresident_gross_up_share : ctx.lookup.ordinary_gross_up_share;
const rate = special ? ctx.lookup.special_nonresident_rate : ctx.lookup.ordinary_rate;
return round(base / share * rate, ctx.lookup.minor_unit, 'HALF_UP');

