const inputs = get(ctx.entry, 'inputs', {});
const year = get(inputs, 'tax_year', null);
const payment = get(inputs, 'compensation_payment_case_id', '');
if (year === null) return false;
if (!(year >= ctx.lookup.minimum_year)) return false;
return String(payment).trim() !== '';

MINIMUM_WAGE_FLOOR.validate:
const employer = get(ctx.subject, 'employer.entity_extension_data', {});
if (get(employer, 'bmbe_certificate_of_authority', false) === true) return true;
if (get(employer, 'minimum_wage_exemption_approved', false) === true) return true;
const terms = get(ctx.entry, 'terms', {});
const domestic = get(terms, 'statutory_work_category', '') === 'DOMESTIC';
const region = get(ctx.subject, 'employment.terms.work_region', get(employer, 'region', ''));
if (region === '') return true;
const table = domestic ? ctx.lookup.minimum_wage_domestic : ctx.lookup.minimum_wage_by_region;
const start = get(ctx.entry, 'effective_range.from', '9999-12-31');
const rates = table.filter((entry) => entry.region === region && entry.from <= start);
if (rates.length === 0) return false;
const floor = Number(rates.toSorted((a, b) => (a.from < b.from ? 1 : -1))[0].monthly);
const rate = get(terms, 'rate', {});
const amount = Number(get(rate, 'amount', 0));
const unit = get(rate, 'unit', 'MONTHLY');
if (domestic && unit === 'MONTHLY') return amount + 0.005 >= floor;
const hours = Number(get(terms, 'normal_hours_per_day', 0));
// DOLE ch.2: a day is the monthly wage × 12 ÷ the contract week's working days (365 − 52 rest days).
const daysPerYear = 365 - 52 * (7 - Number(get(terms, 'normal_days_per_week', 6)));
const daily = unit === 'DAILY'
	? amount
	: unit === 'HOURLY'
		? amount * hours
		: (amount * 12) / daysPerYear;
// The table's monthly figure is the wage order's daily rate × 313 ÷ 12: the order fixes the day, whatever the work week.
return daily + 0.005 >= (floor * 12) / 313;

MEDICAL_CLAIM.eligibility:
const end = get(ctx.subject.employment, 'effective_range.to', null);
if (ctx.entry.unit !== 'MONEY') return false;
if (!(ctx.entry.quantity > 0)) return false;
if (end != null && !(ctx.entry.incurred_on <= end)) return false;
return true;

DENTAL_CLAIM.eligibility:
const end = get(ctx.subject.employment, 'effective_range.to', null);
if (ctx.entry.unit !== 'MONEY') return false;
if (!(ctx.entry.quantity > 0)) return false;
if (end != null && !(ctx.entry.incurred_on <= end)) return false;
return true;

lookup.entitlement:
// RA 8187 s.2: seven days with full pay for the first four deliveries of the spouse; delivery includes childbirth or any miscarriage.
const deliveries = get(ctx.subject.employment, 'events', []).filter(
	(event) => Object.hasOwn(ctx.lookup.opened_by, event.kind) && event.on <= ctx.event.on
);
return deliveries.length <= ctx.lookup.max_events ? ctx.lookup.grant_days : 0;

// Labor Code art.95; Omnibus Rules Book III Rule V s.1: five days a year after one year of service. Outside it: an establishment
// regularly employing fewer than ten, managerial staff, field personnel and task or contract workers; a kasambahay has ANNUAL_LEAVE_DOMESTIC.
const contract = ctx.subject.employment;
if (get(ctx.subject.employer, 'entity_extension_data.small_establishment', false) === true) return 0;
if (['MANAGERIAL', 'FIELD_PERSONNEL', 'TASK_BASIS', 'DOMESTIC'].includes(get(contract, 'terms.statutory_work_category', ''))) return 0;
const started = get(contract, 'service_started_on', get(contract, 'effective_range.from', ctx.as_of));
return calendar_completed_months(started, ctx.as_of) >= ctx.lookup.service_months ? ctx.lookup.grant_days : 0;

// RA 11210 s.3: 105 days on a live birth, 15 more for a qualified solo parent, 60 on a miscarriage or emergency termination, at every instance.
// s.6 and IRR Rule VIII: of a live birth's leave she may allocate up to seven days, and keeps the rest.
if (ctx.event.kind === 'PREGNANCY_TERMINATION') return ctx.lookup.termination_days;
const facts = get(ctx.subject.employment, 'employee_extension_data', {});
const full = get(facts, 'solo_parent', false) === true ? ctx.lookup.solo_parent_days : ctx.lookup.grant_days;
const birth = get(ctx.subject.employment, 'events', []).find((event) => event.kind === ctx.event.kind && event.on === ctx.event.on);
return full - Math.min(Number(get(birth, 'allocated_days', 0)), ctx.lookup.allocation_days);

// RA 8972 s.8 as amended by RA 11861: seven paid days a year after six months of service, for a solo parent holding a valid ID.
const contract = ctx.subject.employment;
if (get(contract, 'employee_extension_data.solo_parent', false) !== true) return 0;
const started = get(contract, 'service_started_on', get(contract, 'effective_range.from', ctx.as_of));
return calendar_completed_months(started, ctx.as_of) >= ctx.lookup.service_months ? ctx.lookup.grant_days : 0;

// RA 11210 s.6 and IRR Rule VIII s.1: the days the mother allocates, up to seven, over and above paternity leave under RA 8187.
const allocation = get(ctx.subject.employment, 'events', []).find(
	(event) => event.kind === ctx.event.kind && event.on === ctx.event.on
);
return Math.min(Number(get(allocation, 'allocated_days', ctx.lookup.grant_days)), ctx.lookup.grant_days);
